begin
 select jsonb_build_object(
'tables',(select jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,
'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'acl',a.attacl::text) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
'constraints',(select jsonb_agg(jsonb_build_object('name',conname,'definition',pg_get_constraintdef(oid),'validated',convalidated,'deferrable',condeferrable,'deferred',condeferred) order by conname) from pg_constraint where conrelid=c.oid and contype<>'n'),
'indexes',(select jsonb_agg(jsonb_build_object('def',pg_get_indexdef(indexrelid),'valid',indisvalid,'ready',indisready) order by indexrelid::regclass::text) from pg_index where indrelid=c.oid),
'triggers',(select jsonb_agg(jsonb_build_object('def',pg_get_triggerdef(oid),'enabled',tgenabled) order by tgname) from pg_trigger where tgrelid=c.oid and not tgisinternal),
'policies',(select jsonb_agg(jsonb_build_object('name',polname,'command',polcmd,'permissive',polpermissive,'roles',array(select case when r=0 then 'PUBLIC' else pg_get_userbyid(r) end from unnest(polroles) r order by r),'qual',pg_get_expr(polqual,polrelid),'check',pg_get_expr(polwithcheck,polrelid)) order by polname) from pg_policy where polrelid=c.oid),
'acl',(select jsonb_agg(jsonb_build_object('grantee',case when grantee=0 then 'PUBLIC' else pg_get_userbyid(grantee) end,'grantor',pg_get_userbyid(grantor),'privilege',privilege_type,'grantable',is_grantable) order by grantee=0,pg_get_userbyid(grantee),privilege_type) from aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))))) order by c.relname) from pg_class c where c.oid in ('public.seating_plans'::regclass,'public.seating_tables'::regclass,'public.seating_elements'::regclass,'public.seating_templates'::regclass)),
'functions',(select jsonb_agg(jsonb_build_object('signature',n.nspname||'.'||p.proname||'('||oidvectortypes(p.proargtypes)||')','md5',md5(replace(p.prosrc,chr(13),'')),'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'config',p.proconfig,'args',pg_get_function_arguments(p.oid),'return_type',format_type(p.prorettype,null),'language',(select lanname from pg_language where oid=p.prolang),'strict',p.proisstrict,'volatility',p.provolatile,'kind',p.prokind,
'acl',(select jsonb_agg(jsonb_build_object('grantee',case when grantee=0 then 'PUBLIC' else pg_get_userbyid(grantee) end,'grantor',pg_get_userbyid(grantor),'privilege',privilege_type,'grantable',is_grantable) order by grantee=0,pg_get_userbyid(grantee),privilege_type) from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))))) order by n.nspname,p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.proname in ('create_seating_plan_from_template','lock_seating_plan','lock_seating_project','manage_seating_element','manage_seating_plan','manage_seating_table','normalize_seating_appearance','seating_appearance_valid','seating_authorize','seating_element_guard','seating_element_valid','seating_geometry_fits','seating_plan_guard','seating_table_seat_guard','seating_template_guard','set_seating_appearance','validate_seating_template'))) into actual;
 if actual is distinct from expected then raise exception 'FAIL: preset styles schema/source/security mismatch';end if;
